import java.util.Collections;
import java.util.Map;

class Example {
    // Assuming key and value are guaranteed non-null in context
    Map<String, String> createMap(String key, String value) {
        return Collections.singletonMap(key, value);
    }

    // Example where key or value might be null - rule should not apply
    Map<String, String> createMapWithNulls(String key, String nullableValue) {
        return Collections.singletonMap(key, nullableValue);
    }
}

